const [introTarget,setIntroTarget]=useState<Profile|null>(null),[introMessage,setIntroMessage]=useState(""),[introConsent,setIntroConsent]=useState(false),[introError,setIntroError]=useState(""),[conversation,setConversation]=useState<Intro|null>(null),[message,setMessage]=useState(""),[info,setInfo]=useState<"how"|"privacy"|null>(null);
const [introSourceId,setIntroSourceId]=useState("");
