useEffect(()=>{type Context={registerTool:(tool:unknown,options:{signal:AbortSignal})=>void|Promise<void>};const context=(document as Document&{modelContext?:Context}).modelContext;if(!context?.registerTool)return;const controller=new AbortController();const register=(tool:unknown)=>{try{void Promise.resolve(context.registerTool(tool,{signal:controller.signal})).catch(()=>{})}catch{}};
register({name:"filter_opportunities",title:"Filter opportunities",description:"Set the discovery type and text search, then show matching profiles. This does not contact anyone.",inputSchema:{type:"object",properties:{kind:{type:"string",enum:["startup","investor"]},query:{type:"string",maxLength:100}},required:["kind","query"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async(input:unknown)=>{const i=input as {kind:string;query:string};if(!i||!["startup","investor"].includes(i.kind)||typeof i.query!=="string"||i.query.length>100)throw new Error("Invalid filter.");navigate("discover");chooseKind(i.kind as ProfileKind);setSearch(i.query);setSector("all");setStage("all");setMembersOnly(false);return {kind:i.kind,query:i.query,matching:data.profiles.filter(p=>p.kind===i.kind&&[p.name,p.founder,p.city,p.tagline,...profileSectorNames(p),p.problem,p.solution,p.nextMilestone].join(" ").toLowerCase().includes(i.query.trim().toLowerCase())).map(p=>({id:p.id,name:p.name,demo:p.demo}))}}});
register({name:"open_opportunity",title:"Open opportunity",description:"Open an existing profile for evidence review. This does not request an introduction.",inputSchema:{type:"object",properties:{id:{type:"string"}},required:["id"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async(input:unknown)=>{const id=(input as {id:string})?.id;if(typeof id!=="string")throw new Error("Invalid profile ID.");const p=data.profiles.find(p=>p.id===id);if(!p)throw new Error("Profile unavailable.");openDetail(p);return {id:p.id,name:p.name,demo:p.demo}}});return()=>controller.abort()},[data.profiles,navigate,openDetail]);

function renderCard({p}:{p:Profile;index:number}){return <OpportunityCard key={p.id} profile={p} saved={data.savedIds.includes(p.id)} selected={compared.some(item=>item.id===p.id)} busy={busy} relationship={isFounder?undefined:outgoingRelationship(p.id,data.requests,null)} onSave={()=>void save(p)} onCompare={()=>toggleCompare(p)} onOpen={()=>openDetail(p)} onContact={()=>startIntro(p)} onEdit={()=>startEditor(p.kind,p)}/>}

